export type SuccessReply<Id extends OperationId> = OperationSuccessReplies[Id];

export function operationById(operationId: string): OperationDescriptor | undefined {
  return Object.hasOwn(OPERATIONS, operationId) ? OPERATIONS[operationId as OperationId] : undefined;
}
